alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

create or replace function public.is_team_member(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
  );
$$;

create or replace function public.is_team_editor(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
      and tm.role = 'editor'
  );
$$;

create or replace function public.document_team_id(p_document_id bigint)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select d.team_id from public.documents d where d.id = p_document_id;
$$;

create or replace function public.enforce_document_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.team_id is distinct from old.team_id
     or new.title is distinct from old.title
     or new.created_by is distinct from old.created_by then
    raise exception 'document immutable fields cannot be changed';
  end if;

  if old.deleted_at is not null then
    raise exception 'deleted documents cannot be updated';
  end if;

  if public.is_team_editor(old.team_id) then
    if public.is_team_editor(new.team_id) then
      return new;
    end if;
  end if;

  raise exception 'document team membership change not allowed';
end;
$$;

create trigger enforce_document_update_trigger
before update on public.documents
for each row execute function public.enforce_document_update();

create policy teams_select_member
on public.teams for select to authenticated
using (public.is_team_member(id));

create policy team_members_select_own
on public.team_members for select to authenticated
using (user_id = auth.uid());

create policy documents_select_member
on public.documents for select to authenticated
using (public.is_team_member(team_id) and deleted_at is null);

create policy documents_insert_editor
on public.documents for insert to authenticated
with check (
  public.is_team_editor(team_id)
  and created_by = auth.uid()
  and deleted_at is null
);

create policy documents_update_editor
on public.documents for update to authenticated
using (public.is_team_editor(team_id) and deleted_at is null)
with check (public.is_team_editor(team_id));

create policy documents_delete_creator
on public.documents for delete to authenticated
using (created_by = auth.uid() and deleted_at is null);
