alter table public.restaurants enable row level security;
alter table public.restaurant_staff enable row level security;
alter table public.reservations enable row level security;

create or replace function public.is_restaurant_staff(p_restaurant_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.restaurant_staff
    where restaurant_id = p_restaurant_id
      and user_id = auth.uid()
  );
$$;

create or replace function public.reservation_locked(p_reservation_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.reservations
    where id = p_reservation_id
      and status not in ('booked', 'cancelled')
  );
$$;

create or replace function public.enforce_reservation_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id then
    raise exception 'reservation id cannot be changed';
  end if;

  if new.restaurant_id is distinct from old.restaurant_id then
    raise exception 'reservation restaurant cannot be changed';
  end if;

  if new.user_id is distinct from old.user_id then
    raise exception 'reservation user cannot be changed';
  end if;

  if new.party_size is distinct from old.party_size then
    raise exception 'reservation party size cannot be changed';
  end if;

  if new.reserved_for is distinct from old.reserved_for then
    raise exception 'reservation time cannot be changed';
  end if;

  if old.status = 'booked' then
    if public.is_restaurant_staff(old.restaurant_id) then
      if now() >= old.reserved_for then
        if new.status in ('seated', 'no_show') then
          return new;
        else
          raise exception 'staff can only mark booked reservations as seated or no_show';
        end if;
      else
        raise exception 'staff can only mark passed reservations as seated or no_show';
      end if;
    else
      if new.status = 'cancelled' and now() > old.reserved_for then
        return new;
      else
        raise exception 'only booked reservations can be cancelled';
      end if;
    end if;
  elsif old.status = 'cancelled' then
    raise exception 'cancelled reservations cannot be updated';
  elsif old.status in ('seated', 'no_show') then
    raise exception 'reservations that are already seated or no_show cannot be updated';
  end if;

  raise exception 'invalid reservation update';
end;
$$;

create trigger enforce_reservation_update_trigger
before update on public.reservations
for each row execute function public.enforce_reservation_update();

create policy restaurants_select_authenticated
on public.restaurants for select to authenticated
using (true);

create policy reservations_select_own_or_staff
on public.reservations for select to authenticated
using (user_id = auth.uid() or public.is_restaurant_staff(restaurant_id));

create policy reservations_insert_own_future_booked
on public.reservations for insert to authenticated
with check (
  user_id = auth.uid()
  and reserved_for > now()
  and status = 'booked'
);

create policy reservations_update_own_cancelled
on public.reservations for update to authenticated
using (user_id = auth.uid() and status = 'booked' and reserved_for > now())
with check (user_id = auth.uid() and status = 'cancelled');

create policy reservations_update_staff_status
on public.reservations for update to authenticated
using (public.is_restaurant_staff(restaurant_id) and status = 'booked')
with check (public.is_restaurant_staff(restaurant_id) and status in ('seated', 'no_show'));

revoke all on table public.restaurants from public, anon, authenticated;
revoke all on table public.restaurant_staff from public, anon, authenticated;
revoke all on table public.reservations from public, anon, authenticated;
revoke all on sequence public.reservations_id_seq from public, anon, authenticated;

grant select on table public.restaurants to authenticated;
grant select on table public.restaurant_staff to authenticated;
grant select on table public.reservations to authenticated;
grant insert (restaurant_id, user_id, reserved_for, party_size) on table public.reservations to authenticated;
grant update (status) on table public.reservations to authenticated;
grant usage, select on sequence public.reservations_id_seq to authenticated;

grant all on table public.restaurants to service_role;
grant all on table public.restaurant_staff to service_role;
grant all on table public.reservations to service_role;
grant all on sequence public.reservations_id_seq to service_role;

revoke all on function public.is_restaurant_staff(bigint) from public, anon, authenticated, service_role;
revoke all on function public.reservation_locked(bigint) from public, anon, authenticated, service_role;
revoke all on function public.enforce_reservation_update() from public, anon, authenticated, service_role;

grant execute on function public.is_restaurant_staff(bigint) to authenticated, service_role;
grant execute on function public.reservation_locked(bigint) to authenticated, service_role;
grant execute on function public.enforce_reservation_update() to authenticated, service_role;
