create or replace function public.enforce_reservation_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id then
    raise exception 'reservation id cannot be changed';
  end if;

  if new.restaurant_id is distinct from old.restaurant_id then
    raise exception 'reservation restaurant cannot be changed';
  end if;

  if new.user_id is distinct from old.user_id then
    raise exception 'reservation user cannot be changed';
  end if;

  if new.party_size is distinct from old.party_size then
    raise exception 'reservation party size cannot be changed';
  end if;

  if old.status = 'booked' and public.reservation_future(old.reserved_for) then
    if auth.uid() is distinct from old.user_id then
      raise exception 'only the reservation maker can update a future booked reservation';
    end if;

    if new.status = 'cancelled' then
      return new;
    end if;
  end if;

  if old.status = 'booked' and public.is_restaurant_staff(old.restaurant_id) then
    if public.reservation_future(old.reserved_for) then
      raise exception 'staff cannot update a future reservation';
    end if;

    if new.status in ('seated', 'no_show') then
      return new;
    end if;
  end if;

  raise exception 'invalid reservation status transition';
end;
$$;

