create or replace function public.enforce_stock_insert()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if public.auditor() then
    raise exception 'auditors cannot change stock';
  end if;

  if new.location_id is distinct from (select l.id from public.locations l where l.id = new.location_id) then
    raise exception 'invalid location_id';
  end if;

  if public.location_frozen(new.location_id) then
    raise exception 'location is frozen';
  end if;

  if not exists (
    select 1
    from public.location_staff ls
    where ls.location_id = new.location_id
      and ls.user_id = public.current_user_id()
  ) then
    raise exception 'not staff at this location';
  end if;

  return new;
end;
$$;

create or replace function public.enforce_stock_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if public.auditor() then
    raise exception 'auditors cannot change stock';
  end if;

  if public.current_user_id() is distinct from (select ls.user_id from public.location_staff ls where ls.location_id = old.location_id) then
    raise exception 'not staff at this location';
  end if;

  if public.location_frozen(old.location_id) then
    raise exception 'location is frozen';
  end if;

  if new.location_id is distinct from old.location_id then
    raise exception 'cannot move stock to another location';
  end if;

  if not exists (
    select 1
    from public.location_staff ls
    where ls.location_id = new.location_id
      and ls.user_id = public.current_user_id()
  ) then
    raise exception 'not staff at new location';
  end if;

  return new;
end;
$$;

create or replace function public.enforce_stock_delete()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return old;
  end if;

  if public.auditor() then
    raise exception 'auditors cannot change stock';
  end if;

  if public.current_user_id() is distinct from (select ls.user_id from public.location_staff ls where ls.location_id = old.location_id) then
    raise exception 'not staff at this location';
  end if;

  if public.location_frozen(old.location_id) then
    raise exception 'location is frozen';
  end if;

  return old;
end;
$$;

create trigger enforce_stock_insert
before insert on public.stock
for each row execute function public.enforce_stock_insert();

create trigger enforce_stock_update
before update on public.stock
for each row execute function public.enforce_stock_update();

create trigger enforce_stock_delete
before delete on public.stock
for each row execute function public.enforce_stock_delete();

