create or replace function public.prevent_location_staff_changes()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.id is distinct from (select l.id from public.locations l where l.name = new.name) then
      raise exception 'cannot insert location';
    end if;
    if new.is_frozen is distinct from (select l.is_frozen from public.locations l where l.id = new.id) then
      raise exception 'cannot update location frozen state';
    end if;
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.location_id is distinct from (select l.id from public.locations l where l.name = (select l.name from public.locations l where l.id = new.location_id)) then
      raise exception 'invalid location_staff entry';
    end if;
    if new.user_id is distinct from public.current_user_id() then
      raise exception 'cannot insert staff row for another user';
    end if;
    return new;
  end if;

  if tg_op in ('UPDATE', 'DELETE') then
    raise exception 'location_staff rows cannot be updated or deleted through the app';
  end if;

  return new;
end;
$$;

