create or replace function public.issue_guard()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.project_id is distinct from old.project_id
     or new.title is distinct from old.title then
    raise exception 'immutable issue fields';
  end if;

  if not public.can_see_issue(old.id) then
    raise exception 'issue not visible';
  end if;

  if old.is_confidential is distinct from new.is_confidential then
    if not public.is_project_maintainer(old.project_id) then
      raise exception 'only maintainers can change confidentiality';
    end if;
  end if;

  if new.status is distinct from old.status then
    if old.status <> 'open' then
      raise exception 'issue status is locked';
    end if;
    if new.status not in ('open', 'in_progress', 'closed') then
      raise exception 'invalid issue status';
    end if;
  end if;

  return new;
end;
$$;

create trigger issue_guard_trigger
before insert or update on public.issues
for each row execute function public.issue_guard();

