create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_envelope public.envelopes%rowtype;
  v_signed_at timestamptz;
  v_status text;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_envelope
  from public.envelopes
  where id = p_envelope_id
  for update;

  if not found then
    raise exception 'envelope not found';
  end if;

  if v_envelope.status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  select * into v_envelope
  from public.envelopes
  where id = p_envelope_id
  for update;

  if not exists (
    select 1
    from public.envelope_recipients r
    where r.envelope_id = p_envelope_id and r.user_id = v_uid
  ) then
    raise exception 'not a recipient';
  end if;

  if exists (
    select 1
    from public.envelope_recipients r
    where r.envelope_id = p_envelope_id and r.user_id = v_uid and r.signed_at is not null
  ) then
    raise exception 'already signed';
  end if;

  select r.sign_order into v_signed_at
  from public.envelope_recipients r
  where r.envelope_id = p_envelope_id and r.user_id = v_uid;

  if not found then
    raise exception 'recipient not found';
  end if;

  if not exists (
    select 1
    from public.envelope_recipients r
    where r.envelope_id = p_envelope_id and r.sign_order < v_signed_at and r.signed_at is not null
  ) then
    raise exception 'previous recipient has not signed';
  end if;

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = v_uid;

  update public.envelopes
  set status = (
    select case
      when count(*) = (select count(*) from public.envelope_recipients r where r.envelope_id = e.id)
      then 'completed'
      else e.status
    end
    from public.envelopes e
    where e.id = p_envelope_id
  )
  where id = p_envelope_id;

  select status into v_status from public.envelopes where id = p_envelope_id;
  return v_status;
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_envelope public.envelopes%rowtype;
  v_status text;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_envelope
  from public.envelopes
  where id = p_envelope_id
  for update;

  if not found then
    raise exception 'envelope not found';
  end if;

  if v_envelope.sender_id <> v_uid then
    raise exception 'only sender can void';
  end if;

  if v_envelope.status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  select status into v_status from public.envelopes where id = p_envelope_id;
  return v_status;
end;
$$;
