set search_path = ''
as $$
  select d.org_id
  from public.devices d
  where d.id = p_device_id;
$$;

create or replace function public.prevent_device_commands_modification()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.issued_by is distinct from auth.uid() then
      raise exception 'device commands must be issued by the current user';
    end if;

    if new.command not in ('locate', 'lock', 'wipe') then
      raise exception 'invalid device command';
    end if;

    return new;
  else
    raise exception 'device commands cannot be updated or deleted';
  end if;
end;
$$;

create trigger prevent_device_commands_modification_trigger
before insert or update or delete on public.device_commands
for each row execute function public.prevent_device_commands_modification();

create policy devices_select_assigned_or_admin
on public.devices for select to authenticated
using (assigned_to = auth.uid() or public.is_org_admin(org_id));

create policy device_commands_select_assigned_or_admin
on public.device_commands for select to authenticated
using (assigned_to = auth.uid() or public.is_org_admin(public.device_org_id(device_id)));

create policy device_commands_insert_authorized
on public.device_commands for insert to authenticated
with check (
  issued_by = auth.uid()
  and command in ('locate', 'lock', 'wipe')
  and (
    (command in ('locate', 'lock') and public.is_device_assigned(device_id))
    or public.is_org_admin(public.device_org_id(device_id))
  )
);

revoke all on table public.org_admins from public, anon, authenticated;
revoke all on table public.devices from public, anon, authenticated;
revoke all on table public.device_commands from public, anon, authenticated;
revoke all on sequence public.device_commands_id_seq from public, anon, authenticated;

grant select on table public.devices to authenticated;
grant select on table public.device_commands to authenticated;
grant insert (device_id, command, issued_by) on table public.device_commands to authenticated;

grant all on table public.org_admins to service_role;
grant all on table public.devices to service_role;
grant all on table public.device_commands to service_role;
grant all on sequence public.device_commands_id_seq to service_role;
