create or replace function public.reviews_before_insert()
returns trigger
language plpgsql
as $$
begin
  if auth.uid() is null then
    raise exception 'reviews insert requires authenticated user';
  end if;

  if new.reviewer_id is distinct from auth.uid() then
    raise exception 'reviewer_id must match authenticated user';
  end if;

  if public.is_reviewer() then
    raise exception 'reviewers cannot review their own proposals';
  end if;

  perform 1
  from public.proposals p
  where p.id = new.proposal_id
  for update;

  if not exists (select 1 from public.proposals p where p.id = new.proposal_id) then
    raise exception 'proposal does not exist';
  end if;

  if public.proposal_status(new.proposal_id) not in ('submitted', 'accepted', 'rejected') then
    raise exception 'proposal is not in a valid status';
  end if;

  if public.proposal_status(new.proposal_id) = 'submitted' then
    if exists (
      select 1
      from public.reviews r
      where r.proposal_id = new.proposal_id
        and r.reviewer_id = auth.uid()
    ) then
      raise exception 'review already exists';
    end if;
  else
    raise exception 'only submitted proposals can be reviewed';
  end if;

  return new;
end;
$$;

create or replace function public.reviews_before_update()
returns trigger
language plpgsql
as $$
begin
  if auth.uid() is null then
    raise exception 'reviews update requires authenticated user';
  end if;

  if new.reviewer_id is distinct from auth.uid() then
    raise exception 'reviewer_id must match authenticated user';
  end if;

  if public.is_reviewer() then
    raise exception 'reviewers cannot review their own proposals';
  end if;

  perform 1
  from public.proposals p
  where p.id = new.proposal_id
  for update;

  if not exists (select 1 from public.proposals p where p.id = new.proposal_id) then
    raise exception 'proposal does not exist';
  end if;

  if public.proposal_status(new.proposal_id) not in ('submitted', 'accepted', 'rejected') then
    raise exception 'proposal is not in a valid status';
  end if;

  if public.proposal_status(new.proposal_id) = 'submitted' then
    if exists (
      select 1
      from public.reviews r
      where r.proposal_id = new.proposal_id
        and r.reviewer_id = auth.uid()
    ) then
      return new;
    end if;
  else
    raise exception 'only submitted proposals can be reviewed';
  end if;

  raise exception 'review cannot be updated';
end;
$$;

create trigger reviews_before_insert_trigger
before insert on public.reviews
for each row execute function public.reviews_before_insert();

create trigger reviews_before_update_trigger
before update on public.reviews
for each row execute function public.reviews_before_update();
