    select 1
    from public.hoa_admins h
    where h.user_id = auth.uid()
  );
$$;

create or replace function public.active_permit_count(p_unit_id bigint)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select count(*)
  from public.permits p
  where p.unit_id = p_unit_id
    and p.revoked = false
    and p.valid_until >= current_date;
$$;

create or replace function public.enforce_permit_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id then
    raise exception 'permit id cannot be changed';
  end if;

  if old.revoked = true then
    raise exception 'revoked permits cannot be modified';
  end if;

  if public.is_hoa_admin() then
    if new.revoked = false then
      raise exception 'permits cannot be un-revoked';
    end if;
    return new;
  end if;

  if not public.is_resident((select r.unit_id from public.residents r where r.user_id = auth.uid())) then
    raise exception 'not authorized to modify this permit';
  end if;

  if new.valid_until is distinct from old.valid_until then
    raise exception 'validity cannot be changed by residents';
  end if;

  if new.revoked is distinct from old.revoked then
    raise exception 'revocation status cannot be changed by residents';
  end if;

  if new.plate = old.plate then
    return new;
  end if;

  if new.valid_until < old.valid_until then
    raise exception 'validity cannot be reduced';
  end if;

  return new;
end;
$$;

create trigger enforce_permit_update_trigger
before update on public.permits
for each row execute function public.enforce_permit_update();

