on public.residents for select to authenticated
using (user_id = auth.uid());

create policy permits_select_resident
on public.permits for select to authenticated
using (public.is_resident(unit_id));

create policy permits_select_hoa_admin
on public.permits for select to authenticated
using (public.is_hoa_admin());

create policy permits_insert_resident
on public.permits for insert to authenticated
with check (
  public.is_resident(unit_id)
  and not revoked
  and valid_until <= (current_date + interval '365 days')
  and public.active_permit_count(unit_id) < 2
);

create policy permits_update_resident
on public.permits for update to authenticated
using (public.is_resident(unit_id) and not revoked)
with check (public.is_resident(unit_id) and not revoked);

create policy permits_update_hoa_admin_revoke
on public.permits for update to authenticated
using (public.is_hoa_admin() and not revoked)
with check (public.is_hoa_admin() and revoked);

