grant select on table public.residents to authenticated;
grant select on table public.hoa_admins to authenticated;
grant select, insert, update on table public.permits to authenticated;
grant usage, select on sequence public.permits_id_seq to authenticated;

grant all on table public.residents to service_role;
grant all on table public.hoa_admins to service_role;
grant all on table public.permits to service_role;
grant all on sequence public.permits_id_seq to service_role;

create policy residents_select_own
on public.residents for select to authenticated
using (user_id = auth.uid());

create policy residents_select_unit_permits
on public.permits for select to authenticated
using (public.is_resident(unit_id));

create policy hoa_admins_select_all_permits
on public.permits for select to authenticated
using (public.is_hoa_admin());

create policy hoa_admins_select_all_residents
on public.residents for select to authenticated
using (public.is_hoa_admin());

create policy hoa_admins_select_all_hoa_admins
on public.hoa_admins for select to authenticated
using (public.is_hoa_admin());

create policy residents_insert_unit_permits
on public.permits for insert to authenticated
with check (
  not revoked
  and valid_until <= (current_date + interval '365 days')
  and public.active_permit_count(unit_id) < 2
  and public.is_resident(unit_id)
);

create policy residents_update_unit_permits
on public.permits for update to authenticated
using (public.is_resident(unit_id))
with check (public.is_resident(unit_id));

create policy hoa_admins_update_permits_revoke
on public.permits for update to authenticated
using (public.is_hoa_admin())
with check (public.is_hoa_admin() and revoked = true);
